<div class="page-title"><div><h2>حساب کاربران</h2></div></div>
<section class="card"><form method="get" class="form-inline mb-3"><input type="hidden" name="route" value="plugin/accounting/accounts"><input class="form-control" name="q" value="<?= e($_GET['q'] ?? '') ?>" placeholder="جستجوی نام، موبایل یا نام کاربری"><button class="btn btn-primary" type="submit">جستجو</button></form><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>کاربر</th><th>نقش</th><th>موبایل</th><th>شماره حساب</th><th>مانده</th><th>عملیات</th></tr></thead><tbody><?php foreach (($accounts ?? []) as $account): ?><tr><td><?= e($account['full_name']) ?></td><td><?= e(role_label($account['role'])) ?></td><td dir="ltr"><?= e($account['mobile'] ?: '-') ?></td><td dir="ltr"><?= e($account['account_number'] ?: '-') ?></td><td><?= money_toman($account['balance']) ?></td><td><a class="btn btn-sm btn-light" href="<?= e(url('plugin/accounting/ledger/' . (int) $account['id'])) ?>">مشاهده دفترکل</a></td></tr><?php endforeach; ?><?php if (empty($accounts)): ?><tr><td colspan="6" class="empty">نتیجه‌ای پیدا نشد.</td></tr><?php endif; ?></tbody></table></div></section>
